files.home:.config/opencode/opencode.json:
{
  "agent": {
    "cortex-sync": {
      "mode": "primary",
      "description": "PRE-FLIGHT: Context gathering and spec preparation.",
      "prompt": "{file:{{HOME}}/.config/opencode/skills/cortex-sync.md}",
      "permission": {
        "read": "allow",
        "write": "deny",
        "edit": "deny",
        "bash": "deny"
      }
    },
    "cortex-SDDwork": {
      "mode": "primary",
      "description": "ORCHESTRATOR: Fast Track direct edits or Deep Track delegation.",
      "prompt": "{file:{{HOME}}/.config/opencode/skills/cortex-SDDwork.md}",
      "permission": {
        "read": "allow",
        "write": "allow",
        "edit": "allow",
        "bash": "ask",
        "task": "allow"
      }
    },
    "cortex-documenter": {
      "mode": "primary",
      "description": "CLOSING ANCHOR: Editorial documentation + Session close (Phase 09.A+).",
      "prompt": "{file:{{HOME}}/.config/opencode/skills/cortex-documenter.md}",
      "permission": {
        "read": "allow",
        "write": "allow",
        "edit": "allow",
        "bash": "deny",
        "task": "deny"
      }
    }
  },
  "mcp": {
    "cortex": {
      "type": "local",
      "command": [
        "cortex",
        "mcp-server",
        "--stdio",
        "--project-root",
        "{{ROOT}}"
      ],
      "enabled": true,
      "environment": {
        "PYTHONWARNINGS": "ignore"
      }
    }
  }
}

